 * are consumed in order of expiresAtMs ascending, ties broken by grantId ascending
 * (UTF-16 code-unit order). Inputs are never mutated; `updatedGrants` contains
 * cloned grants in original array order with decremented remainingCents.
 *
 * @param {number} chargeCents
 * @param {Array<{ grantId: string, remainingCents: number, effectiveFromMs: number, expiresAtMs: number }>} grants
 * @param {number} asOfMs
 * @returns {{ appliedCents: number, remainingChargeCents: number, allocations: Array<{ grantId: string, appliedCents: number }>, updatedGrants: Array<object> }}
 */
export function applyCredits(chargeCents, grants = [], asOfMs = 0) {
  if (!(Number.isFinite(chargeCents) && chargeCents >= 0)) {
    throw new LedgerError(
      ERROR_CODES.ERR_INVALID_AMOUNT,
      'chargeCents must be a finite non-negative number'
    );
  }
  assertGrantsAndAsOf(grants, asOfMs);

  const updatedGrants = grants.map(cloneGrant);

  if (chargeCents === 0) {
    return { appliedCents: 0, remainingChargeCents: 0, allocations: [], updatedGrants };
  }

  const order = [];
  for (let i = 0; i < updatedGrants.length; i += 1) {
    if (isEligibleGrant(updatedGrants[i], asOfMs)) order.push(i);
  }
  order.sort((i, j) => {
    const a = updatedGrants[i];
    const b = updatedGrants[j];
    if (a.expiresAtMs !== b.expiresAtMs) return a.expiresAtMs < b.expiresAtMs ? -1 : 1;
    return compareGrantIds(a.grantId, b.grantId) || i - j;
  });

  let remaining = chargeCents;
  let appliedCents = 0;
  const allocations = [];

  for (const idx of order) {
    if (remaining <= 0) break;
    const grant = updatedGrants[idx];
    const take = Math.min(remaining, grant.remainingCents);
    grant.remainingCents -= take;
    remaining -= take;
    appliedCents += take;
    allocations.push({ grantId: grant.grantId, appliedCents: take });
  }

  return {
    appliedCents,
    remainingChargeCents: remaining,
    allocations,
    updatedGrants
  };
}

/**
 * Summarizes total remaining cents across grants eligible at asOfMs
 * (remainingCents > 0 and effectiveFromMs <= asOfMs < expiresAtMs).
 *
 * @param {Array<{ remainingCents: number, effectiveFromMs: number, expiresAtMs: number }>} grants
 * @param {number} asOfMs
 */
export function summarizePoolBalance(grants = [], asOfMs = 0) {
  assertGrantsAndAsOf(grants, asOfMs);
  let availableCents = 0;
  let activeCount = 0;
  for (const g of grants) {
    if (isEligibleGrant(g, asOfMs)) {
      availableCents += g.remainingCents;
      activeCount += 1;
    }
  }
  return { availableCents, activeCount, asOfMs };
}
